/*
  * 复制工作模式编辑界面
  * 2022-09-23
 */

import router from '@ohos.router';
import { MTopBar } from '../components/MTopBar'
import { JobData, Step } from '../model/JobData'

@Entry
@Component
struct Editmodel {
  title: string = '编辑模式'
  jobData: JobData = router.getParams() ? router.getParams()['jobData'] : new JobData('0', '待机', 0, 0, new Array<Step>({
    'power': 0,
    'minute': 0
  }))
  private curPower: string = '0'
  private curStepIndex: number = 0
  powerPickerDialog: CustomDialogController = new CustomDialogController({
    builder: PowerPickerDialog({ curPower: this.curPower, powerPick: this.onPowerPicked }),
    autoCancel: true
  })

  onPowerPicked(power: string): void {
    console.log("=================power:" + power)
    console.log("=================title:" + this.title)
    console.log("=================JobData:" + JSON.stringify(this.jobData))
//    console.log("=================power:" + this.jobData.steps.length)
//    this.jobData.steps[this.curStepIndex].power = Number(power)
  }

  build() {
    Row() {
      Column() {
        MTopBar({ titleStr: this.title })
        Column({ space: 10 }) {
          Row() {
            Text('名称：').fontSize(18).fontWeight(400)
            TextInput({ placeholder: '请输入模式名称', text: this.jobData.name }).width('80%')
              .fontSize(18).fontWeight(400)
          }
          .width('100%')
          .padding({ left: 24, right: 24 })

          Divider().width('100%')

          ForEach(this.jobData.steps, (step: Step, index: number) => {
            Row() {
              Text('功率(W)：').fontSize(16).fontWeight(400)
              Text(step.power + "").fontSize(16).fontWeight(400)
                .backgroundColor('#f3f3f3').borderRadius(20)
                .width(55).padding(10)
                .onClick(() => {
                  console.log("=================JobData:" + JSON.stringify(this.jobData))
                  this.curPower = step.power + ""
                  this.curStepIndex = index
                  this.powerPickerDialog.open()
                })
              //              TextInput({ placeholder: '请输入功率' , text: step.power+""}).width('30%')
              //                .fontSize(16).fontWeight(400)
              Row().width(24)
              Text('时长(秒)：').fontSize(16).fontWeight(400)
              TextInput({ placeholder: '请输入时长', text: step.minute + "" }).width(80)
                .fontSize(16).fontWeight(400)
            }
            .width('100%')
            .padding({ left: 24, right: 24 })
          })

          Divider().margin({left: 24, right: 24})
          Button('添加')
            .onClick(() => {
              this.jobData.steps.push({'power': 100, 'minute': 1})
              console.log("=================JobData:" + JSON.stringify(this.jobData))
            })
        }
      }
      .width('100%')
    }
    .alignItems(VerticalAlign.Top)
    .justifyContent(FlexAlign.Start)
    .height('100%')
  }
}

@CustomDialog
struct PowerPickerDialog {
  private pickerHeight: Length = 400
  private select: number = 0
  private curPower: string = '0'
  private powers: string[] = ["0", "100", "200", "300", '400', "500", "600", "800"]
  dialogController: CustomDialogController
  powerPick: (power: string) => void

  aboutToAppear() {
    this.select = this.powers.indexOf(this.curPower)
    if (this.select < 0 || this.select > this.powers.length - 1) {
      this.select = 0
    }
  }

  build() {
    Column({ space: 8 }) {
      TextPicker({ range: this.powers, selected: this.select })
        .onChange((value: string, index: number) => {
          console.info('Picker item changed, value: ' + value + ', index: ' + index)
          this.curPower = value
        })
        .height(200)
        .defaultPickerItemHeight(16)
        .onAreaChange((oldValue: Area, newValue: Area) => {
          this.pickerHeight = newValue.height
        })
      Button('确定')
        .onClick(() => {
          this.dialogController.close()
          this.powerPick(this.curPower)
        })
      Row().height(8)
    }
    .borderRadius(10)
    .backgroundColor("#fff")
  }
}

