import { EmailAddress, HostConfig, logger, MailAttachment, Properties } from '@coremail/mail_base';
import { getApp } from '../app/app';
import { NodeParam } from '@kit.ArkUI';
import { FolderIdUtil } from '../app/FolderIdUtil';
import { MailFolderTree } from './MailFolder';
import { MailDetail, MailInfo } from './MailDetail';
import { SendPage } from './SendPage';
import { FolderItem, MailItemAbstract, ViewModel } from '../app/viewmodel';

@Entry
@Component
struct TestPage {
  //快捷登录时的用户信息索引
  @State accountIndex: number = 0
  @State message: string = '';
  //treeView参数
  @State folderTree: NodeParam[] = [];
  //选中文件夹下的邮件集合
  @State mails: MailItemAbstract[] = []
  //选中文件夹下的文件夹的标题集合
  @State mailSubjects: string[] = [];
  //点击的treeView的节点id
  @State clickNodeId: number = 0;
  //文件夹索引
  @State currentIndex: number = 0
  //邮件索引
  @State currentMail: number = -1
  //当前是否是快捷登录
  @State quicklyLogin: boolean = true
  //手动登陆时的用户名
  @State userAccount: string = 'hmtest1028@126.com'
  //手动登录时的密码
  @State userPassword: string = 'LIAIKYLSOPXLQDKR'
  //选中邮件时，邮件的信息
  @State mailInfo: MailInfo = new MailInfo()
  //加密复选款状态
  @State secureStatus: boolean = false
  //协议
  @State agreement: string = ''
  //写邮件页面显示
  @State writeMail: boolean = false
  //选中的文件夹fullname
  @State @Watch('changeFolder') selectedFolder: string = ''
  //快捷登录预置账号
  provisionAccounts: Properties[] = [
    {
      userInfo: {
        username: 'hmdemo1028@aliyun.com',
        password: 'password123,./',
      },
      imap: this.getImapParams('imap.aliyun.com'),
      smtp: this.getSmtpParams('smtp.aliyun.com'),
      pop3: this.getPop3Params('pop3.aliyun.com')
    },
    {
      userInfo: {
        username: 'hmtest1028@tom.com',
        password: 'password123,./',
      },
      imap: this.getImapParams('imap.tom.com'),
      smtp: this.getSmtpParams('smtp.tom.com'),
      pop3: this.getPop3Params('pop3.tom.com')
    },
    {
      userInfo: {
        username: `hmtest1028@126.com`,
        password: 'LIAIKYLSOPXLQDKR',
      },
      imap: this.getImapParams('imap.163.com'),
      smtp: this.getSmtpParams('smtp.126.com'),
      pop3: this.getPop3Params('pop.126.com')
    },
    {
      userInfo: {
        username: `hmtest1028@yeah.net`,
        password: 'KWKKQVNQIIZFKLTP',
      },
      imap: this.getImapParams('imap.yeah.net'),
      smtp: this.getSmtpParams('smtp.yeah.net'),
      pop3: this.getPop3Params('pop3.yeah.net')
    }
  ]
  options: SelectOption[] = []
  nodeParam: NodeParam[] = []

  aboutToAppear(): void {
    this.options = this.provisionAccounts.map((item) => {
      return ({
        value: item.userInfo.username
      }) as SelectOption;
    });

  }

  getAllFoldInfo() {
    getApp()
      .testConnect(this.agreement)
      .then(s => {
        this.folderTree = [];
        FolderIdUtil.reset();
        this.message = s ? '连接成功' : '连接失败';
        return getApp().getViewModel()
      })
      .then((value: ViewModel) => {
        value.folderList.map((item: FolderItem, index: number) => {
          const currentFoldName = item.name;
          const cId = FolderIdUtil.getFoldId(item.id);
          const pId = FolderIdUtil.getFatherFoldId(currentFoldName, getApp().getImapStore());
          this.nodeParam.push({
            currentNodeId: cId,
            parentNodeId: pId,
            isFolder: true,
            primaryTitle: item.name
          })
        })
        this.folderTree.push(...this.nodeParam)
        this.mails = value.mailList
      })
      .catch((error: Error) => {
        this.folderTree = [];
        logger.error('error while getAllFoldInfo', error);
      });
  }

  build() {
    Column() {
      Row() {
        // 登录
        if (this.quicklyLogin) {
          Select(this.options)
            .value('选择账号')
            .onSelect((index: number, _: string) => {
              this.accountIndex = index
              // getApp().setAccount(this.provisionAccounts[index])
            })
            .width(300)
        } else {
          Row() {
            Text('账号')
            TextInput({ placeholder: '请输入账号', text: $$this.userAccount })
              .width(200)
            Text('密码')
            TextInput({ placeholder: '请输入密码', text: $$this.userPassword })
              .type(InputType.Password)
              .showPasswordIcon(true)
              .width(200)
            Checkbox()
              .select(false)
              .selectedColor(0xed6f21)
              .onChange((value: boolean) => {
                console.info('Checkbox1 change is' + value)
                this.secureStatus = value
              })
            Text('是否加密')
          }
        }
        Select([{ value: 'imap' }, { value: 'pop3' }])
          .value('协议')
          .selected(0)
          .onSelect((_: number, value: string) => {
            this.agreement = value
          })
          .width(100)

        Button("检查/登录")
          .onClick(() => {
            this.currentIndex = 0
            this.message = '';
            this.mailSubjects = []
            this.nodeParam = []
            this.mailInfo = new MailInfo()
            if (!this.quicklyLogin) {
              this.setAccount();
            }
            this.getAllFoldInfo()
          })
        Button("快捷登录/手动输入")
          .onClick(() => {
            this.quicklyLogin = !this.quicklyLogin
          })
        Button('写邮件')
          .onClick(() => {
            this.writeMail = !this.writeMail
          })
        Blank()
        Text(this.message)
      }
      .padding({ left: 16, right: 16 })
      .alignItems(VerticalAlign.Center)
      .height('15%')
      .width('100%')
      .alignSelf(ItemAlign.Start)

      if (this.writeMail) {
        SendPage({
          prop: this.provisionAccounts[this.accountIndex]
        })
      } else {
        Row() {
          if (this.folderTree.length > 1) {
            MailFolderTree({ folderTree: this.folderTree, selectedFolder: this.selectedFolder })
              .width('15%')
            List() {
              ForEach(this.mails, (item: MailItemAbstract, index: number) => {
                ListItem() {
                  Text(item.subject === '' ? '[无标题]' : item.subject)
                    .fontColor(Color.Gray)
                    .fontSize(16)
                    .padding({ left: 5, top: 5, bottom: 5 })
                    .onAppear(() => {
                    })
                }
                .align(Alignment.Start)
                .padding(5)
                .width('100%')
                .backgroundColor(this.currentMail == index ? '#FFE5B4' : Color.White)
                .borderRadius(3)
                .onClick(() => {
                  this.currentMail = index
                  this.getMailInfo(item)
                })
              }, (item: string, index: number) => {
                return `${index}___${item}`;
              })
            }
            .width('20%')
            .padding({ left: 5 })
            .divider({ strokeWidth: 1, color: Color.Gray })
            .listDirection(Axis.Vertical)

            if (this.mailInfo.id) {
              MailDetail({ itemMailInfo: this.mailInfo })
                .width('100%')
            }
          }
        }
        .alignSelf(ItemAlign.Start)
        .height('85%')
        .alignItems(VerticalAlign.Top)
      }
    }
  }

  getEmailList(inputStr: string): EmailAddress[] {
    if (!inputStr || inputStr.length === 0) {
      return [];
    }
    return inputStr.split(";").map((item) => {
      const itemAddress: EmailAddress = {
        name: `${item}`,
        email: `${item}`
      }
      logger.log(`|`, `${itemAddress}`)
      return itemAddress;
    })
  }

  parseMailAddress(addresses: EmailAddress[]): string {
    return addresses.map((item: EmailAddress) => {
      return item.email;
    }).reduce((p, c) => {
      return `${p}\n${c}`;
    }, "");
  }

  parseAttachments(attachments: MailAttachment[]): string {
    return attachments.map((item: MailAttachment) => {
      return item.getFileName();
    }).reduce((p, c) => {
      return `${p}\n${c}`;
    }, "");
  }

  getMailInfo(mailInfo: MailItemAbstract) {
    this.mailInfo.id = mailInfo.id.toString()
    this.mailInfo.subject = mailInfo.subject
    this.mailInfo.from = mailInfo?.from?.email
    this.mailInfo.digest = mailInfo.digest
    this.mailInfo.time = mailInfo.time.toString()
  }

  changeFolder() {
    this.currentMail = 0
    this.mailSubjects = []
    this.mailInfo = new MailInfo()
    this.mails = []
    getApp().getMails(this.selectedFolder)
      .then((list: MailItemAbstract[]) => {
        this.mails = list
      })
      .catch((e: Error) => {
        logger.debug('get mail list err: ', e)
      })
  }

  setAccount() {
    let accountArr = this.userAccount.split('@')
    logger.debug('etMailType' + accountArr[1])
    let imapHost = this.getMailImapHost(accountArr[1])
    let smtpHost = this.getMailSmtpHost(accountArr[1])
    let pop3Host = this.getMailPop3Host(accountArr[1])
    const props: Properties =
      {
        userInfo: {
          username: this.userAccount,
          password: this.userPassword,
        },
        imap: this.getImapParams(imapHost),
        smtp: this.getSmtpParams(smtpHost),
        pop3: this.getPop3Params(pop3Host)
      }
    // getApp().setAccount(props)
  }

  getImapParams(host: string): HostConfig {
    return {
      host: host,
      port: this.secureStatus ? 993 : 143,
      secure: this.secureStatus ? true : false
    }
  }

  getPop3Params(host: string): HostConfig {
    return {
      host: host,
      port: this.secureStatus ? 995 : 110,
      secure: this.secureStatus ? true : false
    }
  }

  getSmtpParams(host: string): HostConfig {
    return {
      host: host,
      port: this.secureStatus ? 465 : 25,
      secure: this.secureStatus ? true : false
    }
  }

  getMailImapHost(value: string): string {
    let mailType = ''
    logger.debug('mailType' + value)
    switch (value) {
      case "126.com":
        mailType = 'imap.163.com';
        break;
      case "163.com":
        mailType = 'imap.163.com';
        break;
      case "139.com":
        mailType = 'imap.139.com';
        break;
      case "sina.com":
        mailType = 'imap.sina.com';
        break;
      case "sina.cn":
        mailType = 'imap.sina.cn';
        break;
      case "aliyun.com":
        mailType = 'imap.aliyun.com';
        break;
      case "qq.com":
        mailType = 'imap.qq.com';
        break;
      case "outlook.com":
        mailType = 'outlook.office365.com';
        break;
      case "tom.com":
        mailType = 'imap.tom.com';
        break;
      case "yeah.net":
        mailType = 'imap.yeah.net';
        break;
      default:
        mailType = '邮箱格式不正确或其他原因'
    }
    return mailType
  }

  getMailSmtpHost(value: string): string {
    let mailType = ''
    logger.debug('mailType' + value)
    switch (value) {
      case "126.com":
        mailType = 'smtp.126.com';
        break;
