    let list: number[] = []
    for (let i = 1; i <= 10; i++) {
      list.push(i);
    }
    this.data = new MyDataSource52(list)
  }

  build() {
    Column({ space: 5 }) {
      Swiper(this.swiperController) {
        LazyForEach(this.data, (item: string,index:number) => {
          Text(item)
            .width('100%')
            .height('100%')
            .backgroundColor(0xAFEEEE)
            .textAlign(TextAlign.Center)
            .borderColor(Color.Red)
            .borderWidth(0)
            .fontSize(30).key(index+"")
        }, (item: string) => item)
      }
      .cachedCount(2)
     .onAnimationStart((index: number, targetIndex: number) => {
       if (targetIndex !== index) {
         preload(this.photos[targetIndex + 1]);
       }
     })
      .index(1)
      .autoPlay(false)
      .interval(4000)
      .nextMargin(15)
      .vertical(true)
      .prevMargin(6)
      .displayCount(3)
      .borderWidth(0)
      .width(250)
      .height(400)
       .displayMode(SwiperDisplayMode.STRETCH)
      .loop(true)
      .duration(1000)
      .itemSpace(0)
      .key("swiperNextPrevMargin52")

      Row({ space: 12 }) {
        Button('showNext')
          .onClick(() => {
            this.swiperController.showNext()
          })
        Button('showPrevious')
          .onClick(() => {
            this.swiperController.showPrevious()
          })
      }.margin(5)
    }.width('100%')
    .margin({ top: 5 }).key('ColumnSwiper52')
  }
}

