@Component
struct SwiperExample4 {
  private swiperController: SwiperController = new SwiperController()
  private data: MyDataSourceT4 = new MyDataSourceT4([])

  aboutToAppear(): void {
    let list: number[] = []
    for (let i = 1; i <= 10; i++) {
      list.push(i);
    }
    this.data = new MyDataSourceT4(list)
  }

  build() {
    Column({ space: 5 }) {
      Swiper(this.swiperController) {
        LazyForEach(this.data, (item: string, index) => {
          SwiperItemComponent({
            item: item,
          }).reuseId(item.toString())
        }, (item: string) => item)
      }
      .cachedCount(2)
      .index(1)
      .autoPlay(false)
      .interval(4000)
      .key('swiperTestWidth4')
      .loop(true)
      .indicator(
        new DotIndicator()
