import http from '@ohos.net.http'
import { ClassConstructor } from 'class-transformer'
import { YConfig, yDissmissProgress, yIsEmpty, yLog, yShowProgress, yToast } from '../../../index'
import { yJson2Model, yModel, yObject2Json } from './json'

class _YResponseBaseModel {
  root: _YResponseModel = new _YResponseModel()
}

class _YResponseModel {
  result: Object[] = []
  code: string = "y_code"
  message: string = ""
}

interface _YPostOption {
  jkid: string
  jkparams?: Record<string, Object | null> | null
  showProgress?: boolean
  showErrorToast?: boolean
}

/*
 * yPost(
      {
        jkid: "01A01",
        jkparams: {},
      },
      (isSuccess, results) => {
        if (isSuccess) {
          yLog(results![0].token)
        }
      },
      UserModel,
    )
 * */
export async function yPost<T>(
  option: _YPostOption,
  callback: ((isSuccess: boolean, results: T[] | null, code: string | null, message: string | null) => void),
  modelType?: ClassConstructor<T> | null,
) {
  option.jkparams ??= null
  option.showProgress ??= true
  option.showErrorToast ??= true
  if (yIsEmpty(YConfig.baseIP)) {
    callback(false, null, "y_999", "请正确配置YFree：baseIP")
    return
  }
  if (yIsEmpty(YConfig.interface)) {
    callback(false, null, "y_999", "请正确配置YFree：interface")
    return
  }
  yLog(`${option.jkid}:request:${option.jkparams == null ? null : yObject2Json(option.jkparams)}`)
  if (option.showProgress) yShowProgress()
  let httpRequest = http.createHttp()
  httpRequest.request(
    `${YConfig.baseIP}${YConfig.interface}`,
    {
      method: http.RequestMethod.POST,
      header: await YConfig.onYHttpHeader(),
      extraData: {
        jkid: option.jkid,
        jkparams: option.jkparams,
      },
      expectDataType: http.HttpDataType.STRING,
      usingCache: false,
      connectTimeout: 15000,
      readTimeout: 15000,
    },
    (err, data) => {
      httpRequest.destroy()
      if (option.showProgress) yDissmissProgress()
      if (!err) {
        if (data.responseCode = http.ResponseCode.OK) {
          let result = yJson2Model(data.result.toString(), _YResponseBaseModel)!
          try {
            yLog(`${option.jkid}:responseSuccess:${yObject2Json(result)}`)
            let root = result.root
            if (root.code == "200") {
              callback(true, root.result.map((e) => {
                if (modelType == null) {
                  return e as T
                } else {
                  return yModel(e, modelType)
                }
              }), root.code, root.message)
            } else if (root.code == "-1001") {
              YConfig.onYPost_1001(root.message)
            } else {
              if (option.showErrorToast) yToast(YConfig.DEBUG ? "网络请求回执message：\n" + root.message : root.message)
              callback(false, null, root.code, root.message)
            }
          } catch (e) {
            let msg = YConfig.DEBUG ? "网络请求回执message解析异常，响应字符串：" + yObject2Json(result) : "网络请求错误，请重试"
            if (option.showErrorToast) yToast(msg)
            callback(false, null, data.responseCode.toString(), msg)
          }
        } else {
          yLog(`${option.jkid}:responseFailure:网络请求错误！！！ErrorNo:${data.responseCode}`)
          if (option.showErrorToast) yToast(YConfig.DEBUG ? "网络请求错误！！！\nErrorNo:" + data.responseCode : "网络请求错误，请重试")
          callback(false, null, data.responseCode.toString(), "网络请求错误")
        }
      } else {
        yLog(`${option.jkid}:responseFailure:网络请求异常！！！Msg:${err.message}`)
        if (option.showErrorToast) yToast(YConfig.DEBUG ? "网络请求异常！！！\nMsg:" + err.message : "网络请求错误，请重试")
        callback(false, null, err.code.toString(), err.message)
      }
    },
  )
}

